using FolderVerse;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using System.Reflection;
using var game=new CheckGame();game.Run();
sealed class CheckGame:Game1
{
    const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;int frame;
    object Get(string name)=>typeof(Game1).GetField(name,F)!.GetValue(this)!;
    void Set(string name,object value)=>typeof(Game1).GetField(name,F)!.SetValue(this,value);
    object Call(string name,params object[] args)=>typeof(Game1).GetMethod(name,F)!.Invoke(this,args)!;
    void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    protected override void LoadContent(){Content.RootDirectory=Path.Combine(AppContext.BaseDirectory,"Content");base.LoadContent();var font=(SpriteFont)Get("_font");foreach(var text in new[]{"ID 123 / 帰還：損傷判定 Head","頭（損傷・未所属扱い）をドラッグ＆ドロップして再配置","移動先が満杯です（出撃中の帰還予約を含む）"}){Check(text.All(c=>font.Characters.Contains(c)),"New damage text is missing a font glyph: "+text);font.MeasureString(text);}Console.WriteLine("PASS: compiled UI font covers damage, return and reservation messages.");var w=(WorldSetup)Get("_setup");w.SetWorld(123);w.SetCast(456);w.SetPlacement(789);w.SelectPlayer(0);int node=w.Nodes.All.First(n=>n.Owner==0).Id;Set("_populationNode",node);var r=w.Robots.Create(1,RobotParts.Complete);Check((bool)Call("CanMoveHangarPart",r,RobotParts.Head),"Captured foreign parts movable");w.Nodes.All[node].Owner=-1;Check(!(bool)Call("CanMoveHangarPart",r,RobotParts.Head),"Neutral foreign part disabled");Check((bool)Call("CanMoveHangarPart",w.Robots.Create(0,RobotParts.Head),RobotParts.Head),"Neutral own part movable");w.Nodes.All[node].Owner=1;Check(!(bool)Call("CanMoveHangarPart",r,RobotParts.Head),"Foreign node disabled");Call("OpenStrategyInspector");Set("_domesticSlide",1f);Set("_trainingOpen",true);Call("TrainingInput",new Point(600,380),true,false);Call("TrainingInput",new Point(600,530),true,false);Check(w.Robots.Training[0].AssemblyPolicy==2,"Assembly dropdown selection");Call("TrainingInput",new Point(600,580),true,false);Call("TrainingInput",new Point(600,735),true,false);Check(w.Robots.Training[0].DeploymentPolicy==2 && w.Robots.Training[1].DeploymentPolicy==3,"Deployment dropdown independent");Call("TrainingInput",new Point(600,760),true,false);Call("TrainingInput",new Point(600,820),true,false);Check(w.Robots.Training[0].WorkerPolicy==0 && w.Robots.Training[0].AssemblyPolicy==2 && w.Robots.Training[0].DeploymentPolicy==2,"Worker dropdown is separate from assembly and combat");}
    protected override void Update(GameTime time){}
    protected override void Draw(GameTime time){if(frame==1){var graphics=(GraphicsDeviceManager)Get("_graphics");graphics.PreferredBackBufferWidth=960;graphics.PreferredBackBufferHeight=540;graphics.ApplyChanges();var policy=((WorldSetup)Get("_setup")).Robots.Training[0];policy.AssemblyPolicy=policy.DeploymentPolicy=policy.WorkerPolicy=3;}GraphicsDevice.Clear(Color.Black);var batch=(SpriteBatch)Get("_spriteBatch");var canvas=(Rectangle)Call("CanvasBounds");batch.Begin(transformMatrix:Matrix.CreateScale(canvas.Width/1920f,canvas.Height/1080f,1)*Matrix.CreateTranslation(canvas.X,canvas.Y,0));Call("DrawTraining");batch.End();var pp=GraphicsDevice.PresentationParameters;var pixels=new Color[pp.BackBufferWidth*pp.BackBufferHeight];GraphicsDevice.GetBackBufferData(pixels);using var texture=new Texture2D(GraphicsDevice,pp.BackBufferWidth,pp.BackBufferHeight);texture.SetData(pixels);using var output=File.Create(Path.Combine(AppContext.BaseDirectory,frame==0?"training-ui.png":"training-ui-small.png"));texture.SaveAsPng(output,pp.BackBufferWidth,pp.BackBufferHeight);Console.WriteLine("PASS: neutral/foreign/captured permissions and training dialog render.");if(++frame==2)Exit();}
}